const lines = stdin.trim().split('\n');
const n = parseInt(lines[0], 10);
const weights = { ui: 1, logic: 2, data: 3, auth: 4, payments: 4 };
let best = null;
for (let i = 1; i <= n; i++) {
  const [name, size, area, tests] = lines[i].split('|').map(s => s.trim());
  const count = parseInt(size, 10);
  let score = weights[area.toLowerCase()] || 2;
  if (count > 400) score += 2;
  else if (count > 100) score += 1;
  if (tests.toLowerCase() !== 'yes') score += 2;
  const level = score >= 6 ? 'HIGH' : score >= 4 ? 'MEDIUM' : 'LOW';
  console.log(`${name}: ${level} (score ${score})`);
  if (!best || score > best.score) best = { name, score };
}
console.log(`Review first: ${best.name}`);
